def source(short, title, kind, locator, url, pattern=None, page=None, note=''):
    matches = sorted((DIST / 'evidence').rglob(pattern)) if pattern else []
    return dict(short=short, title=title, kind=kind, locator=locator, url=url,
                pdf=('/' + matches[0].relative_to(DIST).as_posix() + (f'#page={page}' if page else '')) if matches else url,
                note=note)

